import yfinance as yf; tickers=[x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()]; data=yf.download(tickers,period="5d",progress=False,auto_adjust=True); prices=data["Close"].iloc[-1]; print("\n".join(f"{ticker}: {float(prices[ticker]):.2f}" for ticker in tickers if ticker in prices.index))
